import express from "express";
import path from "path";
import { createServer as createViteServer } from "vite";

// Balanced bracket JSON array extractor to prevent non-greedy regex failures on nested structures
function extractJsonArray(text: string, startIndex: number): string | null {
  let depth = 0;
  let inString = false;
  let escape = false;
  
  for (let i = startIndex; i < text.length; i++) {
    const char = text[i];
    
    if (escape) {
      escape = false;
      continue;
    }
    
    if (char === '\\') {
      escape = true;
      continue;
    }
    
    if (char === '"' || char === "'") {
      if (!inString) {
        inString = true;
      } else {
        inString = false;
      }
      continue;
    }
    
    if (!inString) {
      if (char === '[') {
        depth++;
      } else if (char === ']') {
        depth--;
        if (depth === 0) {
          return text.substring(startIndex, i + 1);
        }
      }
    }
  }
  return null;
}

// Check deep nested arrays for realistic video duration measurements to robustly flag background video media
function hasVideoDuration(array: any[]): boolean {
  for (let i = 2; i < array.length; i++) {
    const el = array[i];
    if (Array.isArray(el)) {
      if (
        el.length >= 1 && 
        typeof el[0] === 'number' && 
        el[0] > 500 && 
        el[0] < 7200000 && 
        el.length <= 10 &&
        el.every(item => typeof item === 'number')
      ) {
        return true;
      }
      if (hasVideoDuration(el)) return true;
    }
  }
  return false;
}

// Deeply search the parsed JSON structure recursively to extract all video and image items matching Google Photos baseUrls
function findMediaItems(
  obj: any, 
  list: { baseUrl: string; isVideo: boolean; width: number; height: number }[] = []
): { baseUrl: string; isVideo: boolean; width: number; height: number }[] {
  if (!obj) return list;
  
  if (Array.isArray(obj)) {
    if (
      obj.length >= 2 &&
      Array.isArray(obj[1]) &&
      typeof obj[1][0] === "string" &&
      obj[1][0].startsWith("https://") &&
      obj[1][0].includes("googleusercontent.com")
    ) {
      const baseUrl = obj[1][0];
      let isVideo = false;
      
      if (obj[9] && Array.isArray(obj[9]) && typeof obj[9][0] === 'number' && obj[9][0] > 0) {
        isVideo = true;
      } else if (obj[12] && Array.isArray(obj[12]) && typeof obj[12][0] === 'number' && obj[12][0] > 0) {
        isVideo = true;
      } else if (obj[15] && Array.isArray(obj[15]) && typeof obj[15][0] === 'number' && obj[15][0] > 0) {
        isVideo = true;
      }
      
      if (!isVideo) {
        isVideo = hasVideoDuration(obj);
      }
      
      list.push({
        baseUrl,
        isVideo,
        width: typeof obj[1][1] === 'number' ? obj[1][1] : 1200,
        height: typeof obj[1][2] === 'number' ? obj[1][2] : 800
      });
    } else {
      for (const child of obj) {
        findMediaItems(child, list);
      }
    }
  } else if (typeof obj === "object") {
    for (const key in obj) {
      if (Object.prototype.hasOwnProperty.call(obj, key)) {
        findMediaItems(obj[key], list);
      }
    }
  }
  return list;
}

async function startServer() {
  const app = express();
  const PORT = 3000;

  // Setup CORS to support external clients like GitHub Pages
  app.use((req, res, next) => {
    const origin = req.headers.origin || "*";
    res.header("Access-Control-Allow-Origin", origin);
    res.header("Access-Control-Allow-Headers", "Origin, X-Requested-With, Content-Type, Accept, Authorization");
    res.header("Access-Control-Allow-Methods", "GET, POST, OPTIONS, PUT, DELETE");
    res.header("Access-Control-Allow-Credentials", "true");
    
    if (req.method === "OPTIONS") {
      return res.sendStatus(200);
    }
    next();
  });

  // Middleware
  app.use(express.json());

  // API routes FIRST
  app.get("/api/health", (req, res) => {
    res.json({ status: "ok" });
  });

  // Fetch shared album API
  app.post("/api/fetch-shared-album", async (req, res) => {
    const { url } = req.body;
    if (!url || typeof url !== "string") {
      return res.status(400).json({ error: "Yêu cầu cung cấp đường dẫn liên kết của Album Google Photos." });
    }

    const cleanUrl = url.trim();
    // Support direct single Google Photos image links as single-image albums gracefully on the server too
    if (
      cleanUrl.includes('googleusercontent.com') ||
      cleanUrl.includes('photos.fife') || 
      cleanUrl.includes('lh3.google.com')
    ) {
      if (
        cleanUrl.includes('/pw/') || 
        cleanUrl.includes('=w') || 
        cleanUrl.includes('=s') || 
        cleanUrl.includes('?authuser') ||
        cleanUrl.includes('-no')
      ) {
        const baseUrl = cleanUrl.split('=')[0];
        const singlePhoto = {
          id: `gp-single-${Date.now()}`,
          url: `${baseUrl}=w1200-h800`,
          thumbnailUrl: `${baseUrl}=w600-h400-c`,
          type: 'image',
          title: 'Ảnh từ Google Photos Link',
          location: 'Khung ảnh Đám mây',
          year: new Date().getFullYear(),
          description: 'Hình ảnh đơn liên kết trực tiếp từ Google Photos.'
        };
        return res.json({
          id: `gp-album-single-${Date.now()}`,
          name: 'Ảnh Đơn Google Photos',
          year: new Date().getFullYear(),
          coverUrl: `${baseUrl}=w600-h400-c`,
          photosCount: 1,
          description: 'Album tự động khởi tạo từ liên kết hình ảnh trực tiếp của bạn.',
          photos: [singlePhoto]
        });
      }
    }

    try {
      // Logic for scraping Google Photos shared album
      const response = await fetch(url, {
        headers: {
          "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
        }
      });

      if (!response.ok) {
        return res.status(400).json({ error: "Không thể kết nối đến liên kết. Hãy đảm bảo bạn đã cấp quyền chia sẻ công khai cho Album." });
      }

      const html = await response.text();
      
      // 1. Try parsing Google Photos media items from embedded AF_initDataCallback JSON with balanced bracket scanner
      const fetchedPhotos: { baseUrl: string; isVideo: boolean; width: number; height: number }[] = [];
      
      const searchStr = "AF_initDataCallback";
      let pos = html.indexOf(searchStr);
      while (pos !== -1) {
        const blockEnd = html.indexOf("});", pos);
        
        // Find "data:" in this callback block
        const targetSearchArea = blockEnd !== -1 ? html.substring(pos, blockEnd + 3) : html.substring(pos, pos + 4000);
        const dataIndex = targetSearchArea.indexOf("data:");
        if (dataIndex !== -1) {
          const arrayStartIndex = targetSearchArea.indexOf("[", dataIndex);
          if (arrayStartIndex !== -1) {
            const absoluteStartIndex = pos + arrayStartIndex;
            const extractedArrayText = extractJsonArray(html, absoluteStartIndex);
            if (extractedArrayText) {
              try {
                const rawData = JSON.parse(extractedArrayText);
                findMediaItems(rawData, fetchedPhotos);
              } catch (err) {
                // Ignore parse errors on secondary or corrupted chunks
              }
            }
          }
        }
        
        pos = html.indexOf(searchStr, pos + 1);
      }

      // Deduplicate parsed photos based on baseUrl to prevent duplicate items
      const seenBaseUrls = new Set<string>();
      const deduplicatedPhotos = fetchedPhotos.filter(item => {
        if (seenBaseUrls.has(item.baseUrl)) return false;
        seenBaseUrls.add(item.baseUrl);
        return true;
      });

      // Extract album details
      const titleMatch = html.match(/<meta\s+property="og:title"\s+content="([^"]+)"/i) || 
                       html.match(/<title>([^<]+)<\/title>/i);
      const albumTitle = titleMatch ? titleMatch[1].replace(' - Google Photos', '').trim() : 'Album Kỷ Niệm Gia Đình';

      let parsedPhotos: any[] = [];

      if (deduplicatedPhotos.length > 0) {
        // Map all parsed files from JSON output with correct item type (video or image)
        parsedPhotos = deduplicatedPhotos.map((item, idx) => {
          return {
            id: `gp-${idx}-${Date.now()}`,
            url: item.isVideo ? `${item.baseUrl}=dv` : `${item.baseUrl}=w1200-h800`,
            thumbnailUrl: `${item.baseUrl}=w600-h400-c`,
            type: item.isVideo ? 'video' : 'image',
            title: item.isVideo ? `Video Kỷ Niệm #${idx + 1}` : `Khoảnh khắc #${idx + 1}`,
            location: albumTitle,
            year: new Date().getFullYear(),
            description: item.isVideo 
              ? `Video gia đình phát trực tiếp từ đám mây (Google Cloud).` 
              : `Hình ảnh được kết nối trực tiếp từ đám mây gia đình.`
          };
        });
      } else {
        // Fallback to the robust regex scanner
        const allMatches: string[] = [];
        const subpathMatches = Array.from(html.matchAll(/https:\/\/lh\d+\.googleusercontent\.com\/([a-zA-Z0-9_-]+)\/([a-zA-Z0-9_-]{50,})/g)).map(m => m[0]);
        allMatches.push(...subpathMatches);
        
        const directMatches = Array.from(html.matchAll(/https:\/\/lh\d+\.googleusercontent\.com\/([a-zA-Z0-9_-]{50,})/g)).map(m => m[0]);
        allMatches.push(...directMatches);

        const baseUrls = allMatches.map(url => url.split('=')[0]);
        const uniqueBaseUrls = Array.from(new Set(baseUrls)).filter(u => {
          return !u.includes('placeholder') && !u.includes('avatar') && !u.includes('profile');
        });

        if (uniqueBaseUrls.length === 0) {
          return res.status(400).json({ error: "Không tìm thấy hình ảnh nào trong Album này. Hãy đảm bảo liên kết là một Album chia sẻ Google Photos công khai và có chứa ảnh." });
        }

        parsedPhotos = uniqueBaseUrls.map((baseUrl, idx) => {
          return {
            id: `gp-${idx}-${Date.now()}`,
            url: `${baseUrl}=w1200-h800`,
            thumbnailUrl: `${baseUrl}=w600-h400-c`,
            type: 'image', // defaults to image under simple scraper
            title: `Khoảnh khắc #${idx + 1}`,
            location: albumTitle,
            year: new Date().getFullYear(),
            description: `Hình ảnh kỷ niệm kết nối từ đám mây.`
          };
        });
      }

      const ogImageMatch = html.match(/<meta\s+property="og:image"\s+content="([^"]+)"/i);
      const firstBaseUrl = fetchedPhotos[0]?.baseUrl || parsedPhotos[0]?.url.split('=')[0];
      const coverUrl = ogImageMatch ? ogImageMatch[1].split('=')[0] + '=w600-h400-c' : `${firstBaseUrl}=w600-h400-c`;

      return res.json({
        id: `gp-album-${Date.now()}`,
        name: albumTitle,
        year: new Date().getFullYear(),
        coverUrl: coverUrl,
        photosCount: parsedPhotos.length,
        description: `Album đồng bộ trực tiếp từ liên kết Google Photos: "${albumTitle}".`,
        photos: parsedPhotos
      });

    } catch (err: any) {
      console.error("Fetch shared album issue:", err);
      return res.status(500).json({ error: "Có lỗi xảy ra khi đồng bộ hình ảnh: " + err.message });
    }
  });

  // Image proxy routing to bypass Google Photos fife / usercontent security referer blocks
  app.get("/api/proxy/image", async (req, res) => {
    const { url } = req.query;
    if (!url || typeof url !== "string") {
      return res.status(400).send("Yêu cầu cung cấp tham số url.");
    }

    try {
      const decodedUrl = decodeURIComponent(url);
      
      // Ensure it is only proxying Google Photos/User Content URLs for safety
      if (
        !decodedUrl.includes('googleusercontent.com') && 
        !decodedUrl.includes('photos.fife') && 
        !decodedUrl.includes('google.com')
      ) {
         return res.status(403).send("Chỉ được phép proxy các miền của Google Photos.");
      }

      const response = await fetch(decodedUrl, {
        headers: {
          "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
        }
      });

      if (!response.ok) {
        console.error(`Unable to proxy image from ${decodedUrl}: status ${response.status}`);
        return res.status(response.status).send(`Failed to stream image ${response.status}`);
      }

      const contentType = response.headers.get("content-type") || "image/jpeg";
      res.setHeader("Content-Type", contentType);
      res.setHeader("Cache-Control", "public, max-age=86400"); // cache 1 day
      
      const arrayBuffer = await response.arrayBuffer();
      const buffer = Buffer.from(arrayBuffer);
      return res.send(buffer);
    } catch (err: any) {
      console.error("Proxy endpoint issue:", err);
      return res.status(500).send("Có lỗi xảy ra trên máy chủ khi proxy hình ảnh: " + err.message);
    }
  });

  // Vite middleware for development
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

startServer();
